\title{The One-Dimensional Discrete 1-Wasserstein Distance:\\ A Formally Verified Theory}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We develop a complete, rigorous theory of the 1-Wasserstein distance $W_1$ for finitely supported probability distributions on the integer grid $\{0,1,\dots,n-1\}$. Working from the Kantorovich formulation of optimal transport, we establish the cumulative-distribution-function (CDF) closed form
\[
W_1(p,q) = \sum_{k=0}^{n-2} \bigl| F_p(k) - F_q(k) \bigr|,
\]
and use it as the computational and theoretical backbone for the entire development. We prove that $W_1$ is a genuine metric on the simplex of distributions---nonnegativity, symmetry, the identity of indiscernibles, and the triangle inequality---and we establish Kantorovich--Rubinstein duality with an \emph{explicit} optimal 1-Lipschitz potential, so duality holds not as an abstract minimax equality but as an attained, constructive identity. We further prove the Dirac isometry $W_1(\delta_a,\delta_b)=|a-b|$, the mean-difference bound $|\Exp_p-\Exp_q|\le W_1(p,q)$, and the primal coupling lower bound $W_1(p,q)\le\cost(\pi)$ valid for every transport plan $\pi$. The development is constructive and self-contained, and forms a foundation for higher-order Wasserstein distances, strong duality via explicit couplings, data-processing contraction, quantitative convergence of empirical measures, and a tropical (max-plus) analogue.
\end{abstract}

\noindent\textbf{Keywords:} optimal transport, Wasserstein distance, Kantorovich duality, cumulative distribution function, transport plan, Lipschitz potential, Dirac isometry, metric space.

\section{Introduction}

Optimal transport asks for the cheapest way to rearrange one distribution of mass into another, where cost is measured by how far mass is carried. First posed by Monge (1781) for moving earthworks, it was given its modern, analytically tractable form by Kantorovich (1942), whose linear-programming relaxation introduced \emph{transport plans} and the duality now bearing his and Rubinstein's names. The resulting \emph{Wasserstein distances} are metrics on spaces of probability measures, indispensable across statistics, economics, image processing, partial differential equations, and machine learning, where the Wasserstein GAN reframed generative modeling around the dual representation of $W_1$.

This paper isolates the cleanest nontrivial setting---finitely supported distributions on a one-dimensional integer grid---and develops its theory completely. In one dimension the optimal transport cost admits a closed form in terms of cumulative distribution functions, sidestepping any explicit optimization over the polytope of transport plans. This closed form makes every structural property of $W_1$ provable by elementary, finitary arguments, and makes the theory directly computable.

We work over the grid $X_n=\{0,1,\dots,n-1\}$ with ground metric $d(i,j)=|i-j|$. Distributions are nonnegative weight vectors summing to one.

\paragraph{Summary of results.}
\begin{itemize}[nosep]
  \item \textbf{CDF closed form} (\texttt{W1\_def}): $W_1(p,q)=\sum_{k=0}^{n-2}|F_p(k)-F_q(k)|$.
  \item \textbf{Metric} (\texttt{W1\_nonneg}, \texttt{W1\_comm}, \texttt{W1\_self\_eq\_zero}, \texttt{eq\_of\_W1\_zero}, \texttt{W1\_triangle}).
  \item \textbf{Duality} (\texttt{kantorovich\_duality}, \texttt{kantorovich\_le}, \texttt{kantorovich\_attained}).
  \item \textbf{Dirac isometry} (\texttt{W1\_dirac}): $W_1(\delta_a,\delta_b)=|a-b|$.
  \item \textbf{Mean bound} (\texttt{abs\_mean\_sub\_le\_W1}): $|\Exp_p-\Exp_q|\le W_1(p,q)$.
  \item \textbf{Primal bound} (\texttt{W1\_le\_transportCost}): $W_1(p,q)\le\cost(\pi)$ for every plan $\pi$.
\end{itemize}

\section{Definitions and basic objects}

\begin{definition}[Distribution]
Fix $n\ge 1$. A \emph{distribution} on $X_n=\{0,\dots,n-1\}$ is a vector $p=(p_0,\dots,p_{n-1})$ with $p_k\ge 0$ and $\sum_{k=0}^{n-1}p_k=1$. We write $\Delta_n$ for the set of such distributions (the standard simplex).
\end{definition}

\begin{definition}[Dirac mass]
For $a\in X_n$, the \emph{Dirac mass} $\delta_a\in\Delta_n$ is $(\delta_a)_k=1$ if $k=a$, else $0$.
\end{definition}

\begin{definition}[Expectation]
The \emph{mean} of $p\in\Delta_n$ is $\Exp_p:=\sum_{k=0}^{n-1}k\,p_k$.
\end{definition}

\begin{definition}[CDF]
The \emph{cumulative distribution function} of $p$ is $F_p(k):=\sum_{j=0}^{k}p_j$ for $k\in\{0,\dots,n-1\}$. It is nondecreasing, $0\le F_p(k)\le 1$, and $F_p(n-1)=1$.
\end{definition}

\begin{definition}[Transport plan]
A \emph{transport plan} between $p,q\in\Delta_n$ is a matrix $\pi=(\pi_{ij})$ with $\pi_{ij}\ge 0$ and marginals $\sum_j\pi_{ij}=p_i$ and $\sum_i\pi_{ij}=q_j$. We write $\Pi(p,q)$; it is a nonempty compact polytope (containing $\pi_{ij}=p_iq_j$).
\end{definition}

\begin{definition}[Transport cost]
For $\pi\in\Pi(p,q)$ and ground metric $d(i,j)=|i-j|$, $\cost(\pi):=\sum_{i,j}|i-j|\,\pi_{ij}$.
\end{definition}

\begin{definition}[1-Wasserstein distance, \texttt{W1\_def}]
For $p,q\in\Delta_n$,
\[
W_1(p,q):=\sum_{k=0}^{n-2}\bigl|F_p(k)-F_q(k)\bigr|.
\]
The top index $n-1$ is omitted because $F_p(n-1)=F_q(n-1)=1$.
\end{definition}

\begin{definition}[1-Lipschitz potential]
A function $\varphi:X_n\to\R$ is \emph{1-Lipschitz} if $|\varphi(k+1)-\varphi(k)|\le 1$ for all $k$; equivalently $|\varphi(i)-\varphi(j)|\le|i-j|$. Write $\Lipone$ for the set of such potentials, and $\Exp_p\varphi:=\sum_k\varphi(k)p_k$.
\end{definition}

\section{The cumulative closed form}

\begin{theorem}[CDF closed form, \texttt{W1\_def}]\label{thm:cdf}
For all $p,q\in\Delta_n$, the Kantorovich optimal transport cost with ground metric $|i-j|$ equals $W_1(p,q)=\sum_{k=0}^{n-2}|F_p(k)-F_q(k)|$.
\end{theorem}
\begin{proof}[Proof sketch]
Decompose each distance $|i-j|$ as a sum of unit steps across the boundaries between consecutive grid points. The \emph{net flow across boundary $k$} (between sites $k$ and $k+1$) is the signed mass moved from $\{0,\dots,k\}$ to $\{k+1,\dots,n-1\}$; the marginal constraints force it to equal $F_p(k)-F_q(k)$. Each unit crossing contributes $1$ to the cost, so $\cost(\pi)\ge\sum_k|F_p(k)-F_q(k)|$ for every $\pi$. The monotone coupling (Section~\ref{sec:alg}) attains this bound, hence equality.
\end{proof}

Evaluating $W_1$ costs $O(n)$ operations (two prefix sums and a sum of absolute differences), versus a linear program over the $n^2$-dimensional transport polytope.

\section{$W_1$ is a metric}

\begin{theorem}[Nonnegativity, \texttt{W1\_nonneg}]
$W_1(p,q)\ge 0$.
\end{theorem}
\begin{proof}[Proof sketch] A finite sum of absolute values is nonnegative. \end{proof}

\begin{theorem}[Symmetry, \texttt{W1\_comm}]
$W_1(p,q)=W_1(q,p)$.
\end{theorem}
\begin{proof}[Proof sketch] Termwise $|F_p(k)-F_q(k)|=|F_q(k)-F_p(k)|$; sum over $k$. \end{proof}

\begin{theorem}[Self-distance, \texttt{W1\_self\_eq\_zero}]
$W_1(p,p)=0$.
\end{theorem}
\begin{proof}[Proof sketch] Every term is $|F_p(k)-F_p(k)|=0$. \end{proof}

\begin{theorem}[Identity of indiscernibles, \texttt{eq\_of\_W1\_zero}]
If $W_1(p,q)=0$ then $p=q$.
\end{theorem}
\begin{proof}[Proof sketch]
A sum of nonnegative terms vanishes iff each term vanishes, so $F_p(k)=F_q(k)$ for $k\le n-2$; since $F_p(n-1)=F_q(n-1)=1$, the CDFs agree everywhere. Recovering $p$ by first differences, $p_0=F_p(0)$ and $p_k=F_p(k)-F_p(k-1)$, gives $p=q$.
\end{proof}

\begin{theorem}[Triangle inequality, \texttt{W1\_triangle}]
$W_1(p,r)\le W_1(p,q)+W_1(q,r)$.
\end{theorem}
\begin{proof}[Proof sketch]
Apply $|F_p(k)-F_r(k)|\le|F_p(k)-F_q(k)|+|F_q(k)-F_r(k)|$ at each $k$ and sum.
\end{proof}

\begin{corollary}
$(\Delta_n,W_1)$ is a metric space.
\end{corollary}

\section{Kantorovich--Rubinstein duality}

\begin{theorem}[Weak duality, \texttt{kantorovich\_le}]\label{thm:weak}
For every $\varphi\in\Lipone$, $\Exp_p[\varphi]-\Exp_q[\varphi]\le W_1(p,q)$.
\end{theorem}
\begin{proof}[Proof sketch]
With $s_k:=\varphi(k+1)-\varphi(k)$, $|s_k|\le 1$, summation by parts gives
\[
\Exp_p[\varphi]-\Exp_q[\varphi]=\sum_k\varphi(k)(p_k-q_k)=-\sum_{k=0}^{n-2}s_k\bigl(F_p(k)-F_q(k)\bigr),
\]
the boundary terms vanishing as $F_p(n-1)=F_q(n-1)=1$. Bounding $|s_k|\le 1$ termwise yields the claim.
\end{proof}

\begin{theorem}[Attainment, \texttt{kantorovich\_attained}]\label{thm:attain}
Define $\varphi^\star$ by $\varphi^\star(0)=0$ and $\varphi^\star(k+1)-\varphi^\star(k)=-\sgn(F_p(k)-F_q(k))\in\{-1,0,+1\}$. Then $\varphi^\star\in\Lipone$ and $\Exp_p[\varphi^\star]-\Exp_q[\varphi^\star]=W_1(p,q)$.
\end{theorem}
\begin{proof}[Proof sketch]
The increments are signs, so $\varphi^\star$ is 1-Lipschitz. Substituting $s_k=-\sgn(F_p(k)-F_q(k))$ into the identity of Theorem~\ref{thm:weak} gives $\sum_k\sgn(F_p(k)-F_q(k))(F_p(k)-F_q(k))=\sum_k|F_p(k)-F_q(k)|=W_1(p,q)$, using $\sgn(x)\,x=|x|$.
\end{proof}

\begin{theorem}[Kantorovich--Rubinstein duality, \texttt{kantorovich\_duality}]
\[
W_1(p,q)=\max_{\varphi\in\Lipone}\bigl(\Exp_p[\varphi]-\Exp_q[\varphi]\bigr),
\]
attained at the staircase potential $\varphi^\star$.
\end{theorem}
\begin{proof}[Proof sketch]
Theorem~\ref{thm:weak} bounds the supremum above by $W_1$; Theorem~\ref{thm:attain} exhibits a feasible maximizer achieving it.
\end{proof}

This constructive duality is the structure exploited by the Wasserstein GAN: the dual variable $\varphi$ is the 1-Lipschitz ``critic,'' and the training objective is the dual expectation difference, whose optimum equals $W_1$.

\section{Bounds and isometries}

\begin{theorem}[Primal lower bound, \texttt{W1\_le\_transportCost}]
For every $\pi\in\Pi(p,q)$, $W_1(p,q)\le\cost(\pi)$.
\end{theorem}
\begin{proof}[Proof sketch]
The inequality half of Theorem~\ref{thm:cdf}: the net mass crossing boundary $k$ equals $F_p(k)-F_q(k)$, and mass moving $i\to j$ pays for each of its $|i-j|$ boundary crossings, so $\cost(\pi)\ge\sum_k|F_p(k)-F_q(k)|=W_1(p,q)$.
\end{proof}

\begin{theorem}[Dirac isometry, \texttt{W1\_dirac}]
For $a,b\in X_n$, $W_1(\delta_a,\delta_b)=|a-b|$.
\end{theorem}
\begin{proof}[Proof sketch]
$F_{\delta_a}(k)=\mathbf{1}[k\ge a]$. For $a\le b$, $F_{\delta_a}(k)-F_{\delta_b}(k)=\mathbf{1}[a\le k<b]$, which is $1$ for the $b-a$ values $k\in\{a,\dots,b-1\}$; summing gives $b-a$. The case $a>b$ follows by symmetry.
\end{proof}

Thus $a\mapsto\delta_a$ embeds the grid isometrically into $(\Delta_n,W_1)$: $W_1$ restricted to point masses \emph{is} the ground metric.

\begin{theorem}[Mean-difference bound, \texttt{abs\_mean\_sub\_le\_W1}]
$|\Exp_p-\Exp_q|\le W_1(p,q)$.
\end{theorem}
\begin{proof}[Proof sketch]
The identity potential $\varphi_{\mathrm{id}}(k)=k$ has unit increments, so $\varphi_{\mathrm{id}},-\varphi_{\mathrm{id}}\in\Lipone$. Theorem~\ref{thm:weak} applied to both gives $\Exp_p-\Exp_q\le W_1$ and $\Exp_q-\Exp_p\le W_1$.
\end{proof}

The converse fails: $\delta_1$ and $\tfrac12(\delta_0+\delta_2)$ share mean $1$ but have positive $W_1$, so $W_1$ strictly refines comparison of means.

\section{Algorithms}\label{sec:alg}

\paragraph{Closed-form evaluation ($O(n)$).}
Compute prefix sums $F_p,F_q$ and accumulate $\sum_{k<n-1}|F_p(k)-F_q(k)|$.

\paragraph{Optimal dual potential ($O(n)$).}
One left-to-right pass: $\varphi(0)=0$, then $\varphi(k+1)=\varphi(k)-\sgn(F_p(k)-F_q(k))$.

\paragraph{Monotone (north-west-corner) coupling ($O(n)$).}
Greedily match the smallest available source mass to the smallest available target mass; the discrete inverse-CDF (quantile) coupling, whose cost equals $W_1(p,q)$.

\section{Applications}

\textbf{Generative modeling.} The dual form underlies the Wasserstein GAN; unlike $f$-divergences, $W_1$ remains finite and informative even on disjoint supports, where the Dirac isometry shows it degrades as $|a-b|$ rather than saturating.

\textbf{Statistics.} The mean bound certifies that $W_1$-closeness implies first-moment closeness; the CDF form makes empirical convergence tractable.

\textbf{Signal processing.} On a 1D grid, $W_1$ measures perceptual shift rather than bin-wise discrepancy, computable in real time.

\textbf{Certified bounds.} Weak duality and the primal bound bracket $W_1$ from both sides without solving the optimization.

\section{Discussion}

Two identities drive everything: the marginal/flow-conservation identity pinning net boundary flow to the CDF gap, and summation by parts bridging primal cost and dual objective. Duality here is constructive---the maximizer is written down, not asserted abstractly---as is the primal optimum. The closed form is genuinely one-dimensional; higher dimensions are governed by Brenier's theorem and the Monge--Amp\`ere equation and require different tools.

\section{Future directions}

\begin{conjecture}[Strong duality]
The monotone coupling $\pi^\star$ satisfies $\cost(\pi^\star)=W_1(p,q)$, giving $W_1=\min_\pi\cost(\pi)=\max_{\varphi\in\Lipone}(\Exp_p\varphi-\Exp_q\varphi)$. Test: prove $\cost(\pi^\star)$ telescopes to $\sum_k|F_p(k)-F_q(k)|$.
\end{conjecture}

\begin{conjecture}[Order-$r$ hierarchy]
$W_r(p,q)^r=\min_\pi\sum_{i,j}|i-j|^r\pi_{ij}$ is nondecreasing in $r$, with a quantile closed form $W_r^r=\sum_k g_r(k)$; $W_2$ satisfies the discrete Benamou--Brenier identity. Test: monotonicity via power-mean, then the $r=2$ closed form.
\end{conjecture}

\begin{conjecture}[Data-processing contraction]
For a 1-Lipschitz column-stochastic kernel $K$, $W_1(Kp,Kq)\le W_1(p,q)$. Test: lift weak duality through $K$, the key step being that $\varphi\circ K$ stays 1-Lipschitz.
\end{conjecture}

\begin{conjecture}[Quantitative convergence]
For the empirical $\hat p_m$ of $m$ i.i.d.\ samples, $\Exp[W_1(\hat p_m,p)]\le C(n)/\sqrt{m}$ with $C(n)=\Theta(n)$ from the $\sum_k\mathrm{Var}(F_{\hat p_m}(k))$ decomposition. Test: bound each $\Exp|F_{\hat p_m}(k)-F_p(k)|$ by $\sqrt{F_p(k)(1-F_p(k))/m}$ and sum.
\end{conjecture}

\begin{conjecture}[Tropical bridge]
The tropical analogue $W_1^{\mathrm{trop}}(p,q)=\max_k|F_p(k)-F_q(k)|$ (the $L^\infty$ CDF distance, the $r\to\infty$ limit of $W_r$) is a metric and equals an idempotent Kantorovich dual.
\end{conjecture}

\section{Conclusion}

From the single closed form $W_1(p,q)=\sum_k|F_p(k)-F_q(k)|$ flow the metric axioms, a constructive Kantorovich--Rubinstein duality with an explicit optimal potential, the Dirac isometry, the mean-difference bound, and the primal coupling lower bound---a transparent, computable, rigorously justified geometry on the space of distributions.

