function DualPotential(p, q):
    Fp <- 0; Fq <- 0; phi <- [0]
    for k = 0 to n-2:
        Fp <- Fp + p[k]; Fq <- Fq + q[k]
        step <- -sign(Fp - Fq)        # in {-1, 0, +1}
        phi.append(phi[last] + step)
    return phi
